{"implementation":"def solve(case):
    edges = case["edges"]
    refinement = case["refinement"]
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        if gu > gv:
            gu, gv = gv, gu
        key = (gu, gv)
        agg[key] = agg.get(key, 0) + w
    agg_edges = [[g1, g2, w] for (g1, g2), w in sorted(agg.items())]
    membership = sorted([(node, group) for node, group in refinement.items()], key=lambda x: x[0])
    membership_list = [[node, group] for node, group in membership]
    return {"aggregate_edges": agg_edges, "membership": membership_list}
"}
